public class GameActivity extends AppCompatActivity implements SensorEventListener {
    // Sensors & sounds
    private SensorManager sensorManager; private Sensor accelerometer; private Sensor proximitySensor;
    private SoundPool soundPool; private int fruitSoundId=0,bombSoundId=0,blastSoundId=0,gameOverSoundId=0,goldenSoundId=0,winSoundId=0; private boolean soundsReady=false; private int soundsToLoad=0, soundsLoaded=0;
    private boolean accelBaselineSet=false; private float accelBaselineX=0f; private static final float TILT_SENSITIVITY=1.2f; private static final boolean INVERT_TILT=true;
    private volatile float proximityFactor=1f; private static final float PROXIMITY_SLOW_FACTOR=0.45f; private long proximityStateChangedAt=0L; private GameView gameView;

    @Override protected void onCreate(Bundle savedInstanceState){ super.onCreate(savedInstanceState); gameView=new GameView(this); setContentView(gameView); enableImmersive(); sensorManager=(SensorManager)getSystemService(Context.SENSOR_SERVICE); accelerometer=sensorManager.getDefaultSensor(Sensor.TYPE_ACCELEROMETER); proximitySensor=sensorManager.getDefaultSensor(Sensor.TYPE_PROXIMITY); setupSoundPool(); prepareGeneratedSounds(); }
    private void setupSoundPool(){ AudioAttributes attrs=new AudioAttributes.Builder().setUsage(AudioAttributes.USAGE_GAME).setContentType(AudioAttributes.CONTENT_TYPE_SONIFICATION).build(); soundPool=new SoundPool.Builder().setMaxStreams(8).setAudioAttributes(attrs).build(); soundPool.setOnLoadCompleteListener((sp,id,status)->{ if(status==0){ soundsLoaded++; if(soundsLoaded>=soundsToLoad) soundsReady=true; }}); }
    // Simplified for minSdk 31+: deprecated flags removed
    private void enableImmersive(){ Window w=getWindow(); w.setDecorFitsSystemWindows(false); WindowInsetsController c=w.getInsetsController(); if(c!=null){ c.hide(WindowInsets.Type.statusBars() | WindowInsets.Type.navigationBars()); c.setSystemBarsBehavior(WindowInsetsController.BEHAVIOR_SHOW_TRANSIENT_BARS_BY_SWIPE); } }
    @Override public void onWindowFocusChanged(boolean hasFocus){ super.onWindowFocusChanged(hasFocus); if(hasFocus) enableImmersive(); }
    @Override protected void onResume(){ super.onResume(); sensorManager.registerListener(this,accelerometer,SensorManager.SENSOR_DELAY_GAME); if(proximitySensor!=null) sensorManager.registerListener(this,proximitySensor,SensorManager.SENSOR_DELAY_UI); }
    @Override protected void onPause(){ super.onPause(); sensorManager.unregisterListener(this); }
    @Override protected void onDestroy(){ super.onDestroy(); if(soundPool!=null){ soundPool.release(); soundPool=null; } }

    private void prepareGeneratedSounds(){ fruitSoundId=loadGenerated("fruit.wav", genSine(880,0.22f)); bombSoundId=loadGenerated("bomb.wav", genExplosion(false)); blastSoundId=loadGenerated("blast.wav", genExplosion(true)); gameOverSoundId=loadGenerated("gameover.wav", genGameOver()); goldenSoundId=loadGenerated("golden.wav", genGoldenChime()); winSoundId=loadGenerated("win.wav", genWinFanfare()); }
    private int loadGenerated(String name, byte[] wav){ File f=new File(getFilesDir(),name); if(!f.exists()||f.length()==0){ try(FileOutputStream fos=new FileOutputStream(f)){ fos.write(wav);}catch(IOException ignored){} } if(f.exists()){ soundsToLoad++; return soundPool.load(f.getAbsolutePath(),1);} return 0; }
    private byte[] genSine(int freq,float dur){ return buildWav(buildSinePcm(freq,dur,0.5f)); }
    private byte[] genExplosion(boolean blast){ return buildWav(buildExplosionPcm(blast)); }
    private byte[] genGameOver(){ return buildWav(buildTriTonePcm()); }
    private byte[] genGoldenChime(){ return buildWav(buildGoldenPcm()); }
    private byte[] genWinFanfare(){ return buildWav(buildWinFanfarePcm()); }
    private short[] buildSinePcm(int freq,float dur,float vol){ int sr=22050,total=(int)(sr*dur); short[] d=new short[total]; for(int i=0;i<total;i++){ double t=i/(double)sr; double env=Math.min(1.0,t/0.02)*(1.0-Math.pow(t/dur,3)); double v=Math.sin(2*Math.PI*freq*t)*vol*env; d[i]=(short)(v*32767); } return d; }
    private short[] buildExplosionPcm(boolean blast){ int sr=22050; float dur=blast?0.42f:0.5f; int total=(int)(sr*dur); short[] d=new short[total]; Random r=new Random(); for(int i=0;i<total;i++){ double t=i/(double)sr; double env=Math.exp(-4*t); double val=r.nextDouble()*2-1; if(blast){ double pitch=Math.sin(2*Math.PI*(120+(1-t)*260)*t); val=(val*0.5+pitch*0.5);} d[i]=(short)(val*env*32767);} return d; }
    private short[] buildTriTonePcm(){ int sr=22050; int seg=sr/6; int total=seg*6; short[] d=new short[total]; int[] f={660,550,440}; for(int n=0;n<3;n++){ for(int i=0;i<seg*2;i++){ int idx=n*seg*2+i; double t=i/(double)sr; double env=1.0-(i/(double)(seg*2)); double v=Math.sin(2*Math.PI*f[n]*t)*0.45*env; if(idx<d.length) d[idx]=(short)(v*32767); } } return d; }
    private short[] buildGoldenPcm(){ int sr=22050; int[] freqs={1047,1397,1568}; float[] durs={0.12f,0.12f,0.18f}; int total=0; for(float d:durs) total+=(int)(sr*d); short[] data=new short[total]; int cursor=0; for(int i=0;i<freqs.length;i++){ int f=freqs[i]; int samples=(int)(sr*durs[i]); for(int s=0;s<samples && cursor<data.length;s++,cursor++){ double t=s/(double)sr; double env=Math.exp(-6*t); double wave=Math.sin(2*Math.PI*f*t)+0.35*Math.sin(2*Math.PI*f*2*t)+0.15*Math.sin(2*Math.PI*f*3*t); double val=wave*env*0.35; data[cursor]=(short)(Math.max(-1,Math.min(1,val))*32767); } } return data; }
    private short[] buildWinFanfarePcm(){ int sr=22050; int[] seqFreq={659,784,988,1047,988,784,1319}; float[] seqDur={0.10f,0.10f,0.10f,0.18f,0.12f,0.12f,0.30f}; int total=0; for(float d:seqDur) total+=(int)(sr*d); short[] data=new short[total]; int cursor=0; Random r=new Random(); for(int i=0;i<seqFreq.length;i++){ int f=seqFreq[i]; int samples=(int)(sr*seqDur[i]); for(int s=0;s<samples && cursor<data.length;s++,cursor++){ double t=s/(double)sr; double env=Math.exp(-4*t); double vibr=Math.sin(2*Math.PI*(f+5*Math.sin(2*Math.PI*6*t))*t); double overtone=0.3*Math.sin(2*Math.PI*(f*2)*t); double noise=(r.nextDouble()*2-1)*0.02; double val=(vibr+overtone+noise)*0.5*env; if(i==seqFreq.length-1) val*=1.4; if(val>1)val=1; if(val<-1)val=-1; data[cursor]=(short)(val*32767); } } return data; }
    private byte[] buildWav(short[] pcm){ int sr=22050; int dataLen=pcm.length*2; ByteBuffer bb=ByteBuffer.allocate(44+dataLen).order(ByteOrder.LITTLE_ENDIAN); bb.put(new byte[]{'R','I','F','F'}); bb.putInt(36+dataLen); bb.put(new byte[]{'W','A','V','E','f','m','t',' '}); bb.putInt(16); bb.putShort((short)1); bb.putShort((short)1); bb.putInt(sr); bb.putInt(sr*2); bb.putShort((short)2); bb.putShort((short)16); bb.put(new byte[]{'d','a','t','a'}); bb.putInt(dataLen); for(short s:pcm) bb.putShort(s); return bb.array(); }

    @Override public void onSensorChanged(SensorEvent event){ if(event.sensor.getType()==Sensor.TYPE_ACCELEROMETER){ float x=event.values[0]; if(!accelBaselineSet){ accelBaselineX=x; accelBaselineSet=true;} float dx=x-accelBaselineX; if(INVERT_TILT) dx=-dx; dx*=TILT_SENSITIVITY; if(gameView!=null) gameView.setTilt(dx); } else if(event.sensor.getType()==Sensor.TYPE_PROXIMITY){ float d=event.values[0]; float max=event.sensor.getMaximumRange(); float newFactor=(d<max && d>=0)?PROXIMITY_SLOW_FACTOR:1f; if(Math.abs(newFactor-proximityFactor)>0.01f){ proximityFactor=newFactor; proximityStateChangedAt=System.currentTimeMillis(); } } }
    @Override public void onAccuracyChanged(Sensor sensor,int accuracy){}

    class GameView extends SurfaceView implements SurfaceHolder.Callback {
        private SurfaceHolder holder; private Paint paint=new Paint();
        private int basketX,basketY,basketWidth,basketHeight; private int score=0,lives=3; private long startTime; private long remainingMillis=60000; private boolean completedFullTime=false;
        private final List<Fruit> fruits=new ArrayList<>(); private final List<Explosion> explosions=new ArrayList<>(); private final List<Sparkle> sparkles=new ArrayList<>(); private final List<Shockwave> shockwaves=new ArrayList<>(); private final List<ScorePopup> scorePopups=new ArrayList<>(); private final Map<Integer,Drawable> drawableCache=new HashMap<>();
        private Drawable basketDrawable, explosionDrawable, heartDrawable;
        private volatile boolean gameLoopActive=true, playing=true, gameOverSequence=false, gameOverLaunched=false; private long gameOverStartTime=0L, bombFlashUntil=0L; private CountDownTimer timer;
        private static final float BASE_FALL_SPEED=16f, MAX_FALL_SPEED=70f, BASE_SPAWN_INTERVAL=0.55f, MIN_SPAWN_INTERVAL=0.14f; private int fruitFallSpeed=8; private float currentSpawnInterval=BASE_SPAWN_INTERVAL, spawnAccumulator=0f;
        private float tiltFiltered=0f; private static final float TILT_ALPHA=0.28f, DEAD_ZONE=0.04f, MAX_TILT_ABS=7f, MAX_BASKET_SPEED=2400f; private long lastFrameTime=0L;
        private static final int BASKET_RAISE_MARGIN_DP=60; private final Random bgRandom=new Random();
        private final List<Cloud> clouds = new ArrayList<>();
        private final List<GrassBlade> grass = new ArrayList<>();
        GameView(Context ctx){ super(ctx); holder=getHolder(); holder.addCallback(this); basketDrawable=AppCompatResources.getDrawable(getContext(),R.drawable.basket); explosionDrawable=AppCompatResources.getDrawable(getContext(),R.drawable.explosion_fire); heartDrawable=AppCompatResources.getDrawable(getContext(),R.drawable.heart_life); }
        @Override public void surfaceCreated(SurfaceHolder h){ int w=getWidth(), height=getHeight(); basketWidth=(int)(w*0.30f); if(basketWidth<220) basketWidth=220; if(basketWidth>480) basketWidth=480; basketHeight=(int)(basketWidth*0.5f); basketX=w/2-basketWidth/2; int bottomMargin=dp(BASKET_RAISE_MARGIN_DP); int minMargin=(int)(height*0.05f); if(bottomMargin<minMargin) bottomMargin=minMargin; basketY=height-basketHeight-bottomMargin; if(basketY < height*0.40f) basketY=(int)(height*0.40f); startTime=System.currentTimeMillis(); lastFrameTime=startTime; timer=new CountDownTimer(60000,1000){ public void onTick(long m){ remainingMillis=m;} public void onFinish(){ remainingMillis=0; completedFullTime=true; triggerGameOver(); } }.start(); initClouds(); initGrass(); new Thread(this::gameLoop).start(); }
        @Override public void surfaceChanged(SurfaceHolder h,int f,int w,int hh){}
        @Override public void surfaceDestroyed(SurfaceHolder h){ gameLoopActive=false; }
        private int dp(int v){ return (int)(v*getResources().getDisplayMetrics().density); }
        private Drawable getCachedDrawable(int id){ Drawable d=drawableCache.get(id); if(d==null){ d=AppCompatResources.getDrawable(getContext(),id); if(d!=null) drawableCache.put(id,d);} return d; }
        void setTilt(float raw){ if(Float.isNaN(raw)||Float.isInfinite(raw)) return; if(tiltFiltered==0f && lastFrameTime==0L) tiltFiltered=raw; else tiltFiltered += TILT_ALPHA*(raw-tiltFiltered); }
        private void gameLoop(){ while(gameLoopActive){ if(playing) updateGame(); drawGame(); try{ Thread.sleep(16);}catch(InterruptedException ignored){} } }
        private void initClouds(){ clouds.clear(); int count = 6; int w = getWidth(); int h = getHeight(); if(w==0||h==0) return; for(int i=0;i<count;i++){ float scale = 0.6f + bgRandom.nextFloat()*1.4f; float x = bgRandom.nextFloat()*w; float y = h*0.10f + bgRandom.nextFloat()*h*0.30f; float speed = (20f + bgRandom.nextFloat()*40f) * (0.5f + scale*0.3f); clouds.add(new Cloud(x,y,scale,speed)); } }
        private void updateClouds(float dt){ if(clouds.isEmpty()) return; int w=getWidth(); int h=getHeight(); for(Cloud c:clouds){ c.x += c.speed * dt; if(c.x > w + c.width()){ c.x = -c.width() - bgRandom.nextInt(200); c.y = h*0.08f + bgRandom.nextFloat()*h*0.34f; c.scale = 0.6f + bgRandom.nextFloat()*1.4f; c.speed = (20f + bgRandom.nextFloat()*40f) * (0.5f + c.scale*0.3f); } } }
        private void drawClouds(Canvas c){ if(clouds.isEmpty()) return; Paint p = paint; for(Cloud cl:clouds){ cl.draw(c,p); } }
        private void updateDifficulty(float elapsedSec){ float t=Math.min(1f, elapsedSec/60f); float eased=(float)(1-Math.pow(1-t,2)); float targetFall=BASE_FALL_SPEED+(MAX_FALL_SPEED-BASE_FALL_SPEED)*eased; fruitFallSpeed=Math.min((int)MAX_FALL_SPEED, Math.max(6,(int)targetFall)); float interval=BASE_SPAWN_INTERVAL-(BASE_SPAWN_INTERVAL-MIN_SPAWN_INTERVAL)*eased; currentSpawnInterval=Math.max(MIN_SPAWN_INTERVAL, interval); }
        private void updateGame(){ long now=System.currentTimeMillis(); float elapsed=(now-startTime)/1000f; updateDifficulty(elapsed); spawnAccumulator += lastFrameTime==0?0:(now-lastFrameTime)/1000f; while(spawnAccumulator>=currentSpawnInterval){ fruits.add(Fruit.randomFruit(getWidth())); spawnAccumulator -= currentSpawnInterval; } for(int i=fruits.size()-1;i>=0;i--){ Fruit f=fruits.get(i); f.y += (int)((fruitFallSpeed+f.speed)*GameActivity.this.proximityFactor); if(f.y>getHeight()){ fruits.remove(i); continue; } boolean hit = f.y < basketY + basketHeight && f.y + f.size > basketY && f.x < basketX + basketWidth && f.x + f.size > basketX; if(hit){ if(f.isBomb){ lives--; playBombCatch(); createExplosion(f.x+f.size/2,f.y+f.size/2, now); shockwaves.add(new Shockwave(f.x+f.size/2,f.y+f.size/2, now)); bombFlashUntil=now+140; scorePopups.add(ScorePopup.lifeLost(f.x+f.size/2f,f.y)); } else { int add=f.isGolden?20:5; score+=add; if(f.isGolden){ playGoldenChime(); emitSparkles(f.x+f.size/2f, f.y+f.size/2f); scorePopups.add(ScorePopup.golden(f.x+f.size/2f,f.y,add)); } else { playFruitCatch(); scorePopups.add(ScorePopup.positive(f.x+f.size/2f,f.y,add,false)); } } fruits.remove(i); } } for(int i=explosions.size()-1;i>=0;i--) if(explosions.get(i).isFinished(now)) explosions.remove(i); for(int i=scorePopups.size()-1;i>=0;i--) if(scorePopups.get(i).isFinished(now)) scorePopups.remove(i); Iterator<Sparkle> it=sparkles.iterator(); while(it.hasNext()){ Sparkle s=it.next(); s.update(now); if(s.isDead()) it.remove(); } Iterator<Shockwave> sh=shockwaves.iterator(); while(sh.hasNext()){ Shockwave sw=sh.next(); if(sw.isFinished(now)) sh.remove(); } if(lives<=0) triggerGameOver(); }
        private void emitSparkles(float cx,float cy){ int count=14; for(int i=0;i<count;i++){ double ang=(2*Math.PI*i)/count + bgRandom.nextDouble()*0.4 - 0.2; float speed=180+bgRandom.nextFloat()*160; float vx=(float)(Math.cos(ang)*speed); float vy=(float)(Math.sin(ang)*speed); sparkles.add(new Sparkle(cx,cy,vx,vy)); } }
        private void drawSparkles(Canvas canvas,long now){ for(Sparkle s:sparkles) s.draw(canvas, now, paint); }
        private void createExplosion(int cx,int cy,long now){ explosions.add(new Explosion(cx,cy,now)); }
        private void playFruitCatch(){ if(soundsReady && soundPool!=null && fruitSoundId!=0) soundPool.play(fruitSoundId,0.9f,0.9f,1,0,1f); }
        private void playBombCatch(){ if(soundsReady && soundPool!=null && (blastSoundId!=0||bombSoundId!=0)){ int id=blastSoundId!=0?blastSoundId:bombSoundId; soundPool.play(id,0.55f,0.55f,1,0,0.95f);} }
        private void playGoldenChime(){ if(soundsReady && soundPool!=null && goldenSoundId!=0) soundPool.play(goldenSoundId,1f,1f,1,0,1.05f); }
        private void playGameOverSound(){ if(soundsReady && soundPool!=null && gameOverSoundId!=0) soundPool.play(gameOverSoundId,1f,1f,1,0,1f); }
        private void playWinSound(){ if(soundsReady && soundPool!=null && winSoundId!=0) soundPool.play(winSoundId,1f,1f,1,0,1f); }
        private void triggerGameOver(){ if(gameOverSequence) return; playing=false; gameOverSequence=true; gameOverStartTime=System.currentTimeMillis(); if(timer!=null) timer.cancel(); if(completedFullTime && lives>=0) playWinSound(); else playGameOverSound(); }
        private void drawGame(){ Canvas canvas=holder.lockCanvas(); if(canvas==null) return; long now=System.currentTimeMillis(); float dt= lastFrameTime==0?0:(now-lastFrameTime)/1000f; lastFrameTime=now; canvas.drawColor(Color.rgb(135,206,235)); updateClouds(dt); drawClouds(canvas); drawGrass(canvas, now); float tVal=(Math.abs(tiltFiltered)<DEAD_ZONE)?0f:(tiltFiltered - Math.copySign(DEAD_ZONE,tiltFiltered)); float norm=tVal/(MAX_TILT_ABS-DEAD_ZONE); if(norm>1)norm=1; if(norm<-1)norm=-1; float speed=(MAX_BASKET_SPEED + getWidth()*0.45f)*norm; int delta=Math.round(speed*dt); basketX += delta; if(basketX<0) basketX=0; if(basketX>getWidth()-basketWidth) basketX=getWidth()-basketWidth; Drawable b=basketDrawable!=null?basketDrawable:getCachedDrawable(R.drawable.basket); if(b!=null){ b.setBounds(basketX,basketY,basketX+basketWidth,basketY+basketHeight); b.draw(canvas);} else { paint.setColor(Color.rgb(139,69,19)); canvas.drawRect(basketX,basketY,basketX+basketWidth,basketY+basketHeight,paint);} for(Fruit f:fruits){ if(f.isGolden){ drawGoldenCoin(canvas,f,now);} else { Drawable d=getCachedDrawable(f.resId); if(d!=null){ d.setBounds(f.x,f.y,f.x+f.size,f.y+f.size); d.draw(canvas);} } } if(explosionDrawable!=null){ for(Explosion ex:explosions){ float prog=ex.progress(now); int base=160; int size=(int)(base*(0.6f+0.9f*prog)); int half=size/2; explosionDrawable.setBounds(ex.cx-half,ex.cy-half,ex.cx+half,ex.cy+half); explosionDrawable.setAlpha((int)(255*(1f-prog))); explosionDrawable.draw(canvas);} } for(Shockwave sw:shockwaves) sw.draw(canvas, now, paint); drawSparkles(canvas, now); if(now < bombFlashUntil){ int alpha=(int)(180*(bombFlashUntil-now)/140f); if(alpha<0) alpha=0; if(alpha>180) alpha=180; paint.setColor(Color.argb(alpha,255,255,255)); canvas.drawRect(0,0,getWidth(),getHeight(),paint);} paint.setColor(Color.BLACK); paint.setTextSize(48); canvas.drawText("Score: "+score,40,80,paint); int secs=(int)Math.ceil(remainingMillis/1000.0); if(secs<0) secs=0; String timeStr=String.format(Locale.US,"%02d:%02d",secs/60,secs%60); float tw=paint.measureText(timeStr); canvas.drawText(timeStr,getWidth()/2f - tw/2f,80,paint); if(heartDrawable!=null){ int heartSize=80, spacing=20, top=30; int totalWidth=lives*heartSize + (lives-1)*spacing; int startX=getWidth()-totalWidth-40; for(int i=0;i<lives;i++){ int left=startX + i*(heartSize+spacing); heartDrawable.setBounds(left,top,left+heartSize,top+heartSize); heartDrawable.setAlpha(255); heartDrawable.draw(canvas);} } if(GameActivity.this.proximityFactor<1f){ long since=System.currentTimeMillis()-proximityStateChangedAt; int alpha=180; if(since>4000){ float ft=Math.min(1f,(since-4000)/1000f); alpha=(int)(180*(1f-ft)); } if(alpha>0){ paint.setTextSize(54f); paint.setFakeBoldText(true); paint.setColor(Color.argb(alpha,255,255,255)); String msg="SLOW MOTION"; float mw=paint.measureText(msg); canvas.drawText(msg,getWidth()/2f - mw/2f,140,paint);} } drawScorePopups(canvas, now); if(gameOverSequence) drawGameOverOverlay(canvas, now); holder.unlockCanvasAndPost(canvas); }
        class Cloud { float x,y,scale,speed; Cloud(float x,float y,float scale,float speed){ this.x=x; this.y=y; this.scale=scale; this.speed=speed; } float width(){ return 180f*scale; } void draw(Canvas c, Paint p){ p.setAntiAlias(true); int baseAlpha=220; p.setColor(Color.argb(baseAlpha,255,255,255)); float w=width(), h=w*0.55f; float left=x, top=y; float r=h*0.50f; c.drawCircle(left+w*0.25f, top+h*0.55f, r, p); c.drawCircle(left+w*0.47f, top+h*0.40f, r*0.82f, p); c.drawCircle(left+w*0.62f, top+h*0.55f, r*0.70f, p); c.drawCircle(left+w*0.40f, top+h*0.65f, r*0.68f, p); } }
        class GrassBlade { final float baseX, baseY, height, amplitude, speed, phase; final int color; GrassBlade(float baseX,float baseY,float height,float amplitude,float speed,float phase,int color){ this.baseX=baseX; this.baseY=baseY; this.height=height; this.amplitude=amplitude; this.speed=speed; this.phase=phase; this.color=color; } }
        private void initGrass(){ grass.clear(); int w=getWidth(), h=getHeight(); if(w==0||h==0) return; int count=Math.max(40,w/18); for(int i=0;i<count;i++){ float x=i*(w/(float)(count-1)); float heightPx=dp(40)+bgRandom.nextFloat()*dp(90); float amp=dp(6)+bgRandom.nextFloat()*dp(10); float speed=0.6f+bgRandom.nextFloat()*0.8f; float phase=bgRandom.nextFloat()*(float)Math.PI*2f; int shade=160+bgRandom.nextInt(70); grass.add(new GrassBlade(x,h,heightPx,amp,speed,phase, Color.rgb(20,shade/2,20))); } }
        private void drawGrass(Canvas c,long now){ if(grass.isEmpty()) return; Paint p=paint; int groundTop=getHeight()-dp(26); p.setStyle(Paint.Style.FILL); p.setColor(Color.rgb(30,130,40)); c.drawRect(0,groundTop,getWidth(),getHeight(),p); float t=(now-startTime)/1000f; for(GrassBlade g:grass){ float sway=(float)Math.sin(t*g.speed + g.phase)*g.amplitude; float topY=g.baseY - g.height; Path path=new Path(); path.moveTo(g.baseX,g.baseY); path.quadTo(g.baseX + sway*0.5f, g.baseY - g.height*0.55f, g.baseX + sway, topY); p.setStyle(Paint.Style.STROKE); p.setStrokeWidth(4f); p.setStrokeCap(Paint.Cap.ROUND); p.setColor(g.color); c.drawPath(path,p); } p.setStyle(Paint.Style.FILL); }
        private void drawGoldenCoin(Canvas c,Fruit f,long now){ int size=f.size; int cx=f.x+size/2; int cy=f.y+size/2; float radius=size/2f; float phase=(now%1600L)/1600f; double ang=phase*Math.PI*2; float scaleX=0.28f+0.72f*(float)((Math.sin(ang)+1)/2); float face=(float)Math.pow(scaleX,1.2); RadialGradient grad=new RadialGradient(0,0,radius,new int[]{Color.rgb(255,245,180), blend(Color.rgb(255,230,120),Color.rgb(255,215,0), face*0.6f), Color.rgb(170,120,10)}, new float[]{0f,0.68f,1f}, Shader.TileMode.CLAMP); Paint coin=new Paint(Paint.ANTI_ALIAS_FLAG); coin.setShader(grad); c.save(); c.translate(cx,cy); c.scale(scaleX,1f); c.drawCircle(0,0,radius,coin); Paint edge=new Paint(Paint.ANTI_ALIAS_FLAG); edge.setStyle(Paint.Style.STROKE); edge.setStrokeWidth(Math.max(2f,radius*0.08f)); edge.setColor(Color.rgb(180,120,15)); c.drawCircle(0,0,radius-edge.getStrokeWidth()*0.5f, edge); Paint ring=new Paint(Paint.ANTI_ALIAS_FLAG); ring.setStyle(Paint.Style.STROKE); ring.setStrokeWidth(radius*0.14f); ring.setColor(Color.argb(140,255,235,140)); c.drawCircle(0,0,radius*0.55f, ring); if(scaleX>0.55f){ Paint hl=new Paint(Paint.ANTI_ALIAS_FLAG); hl.setColor(Color.argb((int)(140*(scaleX-0.55f)/0.45f),255,255,255)); c.drawCircle(-radius*0.25f,-radius*0.25f,radius*0.45f, hl);} if(scaleX>0.85f){ float streakA=(scaleX-0.85f)/0.15f; Paint streak=new Paint(Paint.ANTI_ALIAS_FLAG); streak.setColor(Color.argb((int)(160*streakA),255,255,255)); float w=radius*0.18f; c.drawRect(-w*0.5f,-radius*0.9f,w*0.5f,radius*0.9f,streak);} c.restore(); }
        private int blend(int c1,int c2,float t){ if(t<0)t=0; else if(t>1)t=1; int a1=(c1>>>24)&0xFF,r1=(c1>>16)&0xFF,g1=(c1>>8)&0xFF,b1=c1&0xFF; int a2=(c2>>>24)&0xFF,r2=(c2>>16)&0xFF,g2=(c2>>8)&0xFF,b2=c2&0xFF; int a=(a1+(int)((a2-a1)*t))&0xFF; int r=(r1+(int)((r2-r1)*t))&0xFF; int g=(g1+(int)((g2-g1)*t))&0xFF; int b=(b1+(int)((b2-b1)*t))&0xFF; return (a<<24)|(r<<16)|(g<<8)|b; }
        private void drawScorePopups(Canvas canvas,long now){ if(scorePopups.isEmpty()) return; float orig=paint.getTextSize(); boolean bold=paint.isFakeBoldText(); paint.setFakeBoldText(true); paint.setTextSize(58f); for(ScorePopup sp:scorePopups){ float prog=sp.progress(now); int alpha=(int)(255*(1f-prog)); if(alpha<0)alpha=0; paint.setColor(Color.argb(alpha,(sp.color>>16)&0xFF,(sp.color>>8)&0xFF,sp.color&0xFF)); float rise=90f*prog; float w=paint.measureText(sp.text); canvas.drawText(sp.text, sp.x - w/2f, sp.y - rise, paint);} paint.setTextSize(orig); paint.setFakeBoldText(bold); }
        private void drawGameOverOverlay(Canvas c,long now){ long elapsed=now-gameOverStartTime; float t=Math.min(1f, elapsed/1200f); int alpha=(int)(200*t); paint.setColor(Color.argb(alpha,0,0,0)); c.drawRect(0,0,getWidth(),getHeight(),paint); boolean win=completedFullTime && lives>=0; String msg=win?"CONGRATULATIONS!":"GAME OVER"; paint.setColor(win?Color.YELLOW:Color.WHITE); paint.setTextSize(90); paint.setFakeBoldText(true); float scale=0.8f+0.2f*t; c.save(); c.scale(scale,scale,getWidth()/2f,getHeight()/2f); float tw=paint.measureText(msg); c.drawText(msg,getWidth()/2f - tw/2f,getHeight()/2f,paint); c.restore(); if(win){ paint.setTextSize(50); paint.setColor(Color.WHITE); String sub="Harvest Complete"; float sw=paint.measureText(sub); c.drawText(sub,getWidth()/2f - sw/2f,getHeight()/2f+80,paint);} if(t>=1f && !gameOverLaunched){ gameOverLaunched=true; post(()->{ Intent intent=new Intent(GameActivity.this, GameOverActivity.class); intent.putExtra("score",score); intent.putExtra("completed",completedFullTime); startActivity(intent); gameLoopActive=false; finish(); }); } }
    }

    // === Data classes (restored) ===
    static class Fruit { int x,y,size,speed,resId; boolean isBomb,isGolden; static Random random=new Random(); static int[] FRUITS={R.drawable.fruit_apple,R.drawable.fruit_orange,R.drawable.fruit_grapes}; static int BOMB=R.drawable.fruit_bomb; static int GOLDEN=R.drawable.fruit_golden; static Fruit randomFruit(int screenWidth){ Fruit f=new Fruit(); f.size=128; f.x=random.nextInt(Math.max(1,screenWidth - f.size)); f.y=-f.size; f.speed=4+random.nextInt(9); boolean bomb=random.nextInt(8)==0; boolean golden=!bomb && random.nextInt(25)==0; f.isBomb=bomb; f.isGolden=golden; if(bomb) f.resId=BOMB; else if(golden) f.resId=GOLDEN; else f.resId=FRUITS[random.nextInt(FRUITS.length)]; return f; } }
    static class Explosion { final int cx,cy; final long startTime; final long duration=500; Explosion(int cx,int cy,long startTime){ this.cx=cx; this.cy=cy; this.startTime=startTime;} float progress(long now){ return Math.min(1f,(now-startTime)/(float)duration);} boolean isFinished(long now){ return now-startTime>duration;} }
    static class Sparkle { float x,y,vx,vy; final long start=System.currentTimeMillis(); final long life=600; float size=18f; Sparkle(float x,float y,float vx,float vy){ this.x=x; this.y=y; this.vx=vx; this.vy=vy;} void update(long now){ x+=vx*0.016f; y+=vy*0.016f; vy+=15f*0.016f;} boolean isDead(){ return System.currentTimeMillis()-start>life;} void draw(Canvas c,long now,Paint p){ long age=now-start; float t=Math.min(1f,age/(float)life); int alpha=(int)(255*(1f-t)); if(alpha<0)alpha=0; p.setColor(Color.argb(alpha,255,225,140)); float s=size*(0.6f+0.4f*(1f-t)); c.drawCircle(x,y,s,p);} }
    static class Shockwave { final int cx,cy; final long start; final long dur=420; Shockwave(int cx,int cy,long start){ this.cx=cx; this.cy=cy; this.start=start;} boolean isFinished(long now){ return now-start>dur;} void draw(Canvas c,long now,Paint p){ float t=Math.min(1f,(now-start)/(float)dur); float radius=40+210*t; int alpha=(int)(180*(1f-t)); if(alpha<0)alpha=0; p.setStyle(Paint.Style.STROKE); p.setStrokeWidth(12f*(1f-t)); p.setColor(Color.argb(alpha,255,200,40)); c.drawCircle(cx,cy,radius,p); p.setStyle(Paint.Style.FILL);} }
    static class ScorePopup { final float x,y; final String text; final int color; final long start; final long duration=800; ScorePopup(float x,float y,String text,int color){ this.x=x; this.y=y; this.text=text; this.color=color; this.start=System.currentTimeMillis(); } static ScorePopup positive(float x,float y,int amount,boolean bonus){ return new ScorePopup(x,y,"+"+amount, bonus? Color.rgb(255,215,0):Color.rgb(0,150,0)); } static ScorePopup lifeLost(float x,float y){ return new ScorePopup(x,y,"Life -1", Color.rgb(200,0,0)); } static ScorePopup golden(float x,float y,int amount){ return new ScorePopup(x,y,"+"+amount, Color.rgb(255,215,0)); } boolean isFinished(long now){ return now-start>duration;} float progress(long now){ return Math.min(1f,(now-start)/(float)duration);} }
}
